    kpis: kpis(ranked, graded, byItem, fraud),
    distribution: distribution(results),
    matrix: confusion(graded, byItem),
    curve: coverage(ranked, byItem, fraud),
    checks: checks(graded, byItem, labels),
    topItems: topItems(ranked, byItem),
  };
}

